class.description:
Only a scene declaring [constant NetwMultiplayer.SCENE_ISOLATION_OWN_WORLD] is hosted in an offscreen [SubViewport], so this view exists only for one.
On scene changes [signal NetwEntity.view_activated] fires.
[codeblock]
func _ready() -> void:
    var entity := Netw.entity(self)
    entity.view_activated.connect(_on_view_activated)

func _on_view_activated() -> void:
    $Rig/SpringArm3D/Camera3D.make_current()
[/codeblock]
